('30000000-0000-0000-0000-000000002132', 'to a certain degree', '/tuː ə ˈsɜːrtn dɪˈɡriː/', 'phrase', 'até certo grau', 'The results support the theory to a certain degree.', 'Os resultados apoiam a teoria até certo grau.', 'C1', array['hedging']),
