('30000000-0000-0000-0000-000000002140', 'presumably', '/prɪˈzuːməbli/', 'adverb', 'presumivelmente', 'Presumably, the delay was caused by a technical issue.', 'Presumivelmente, o atraso foi causado por um problema técnico.', 'C1', array['hedging']),
