('30000000-0000-0000-0000-000000002151', 'subtle', '/ˈsʌtl/', 'adjective', 'sutil', 'There is a subtle difference between the two arguments.', 'Há uma diferença sutil entre os dois argumentos.', 'C1', array['hedging']),
