('30000000-0000-0000-0000-000000002156', 'imply', '/ɪmˈplaɪ/', 'verb', 'sugerir, implicar', 'The tone of the email seemed to imply some frustration.', 'O tom do e-mail parecia sugerir alguma frustração.', 'C1', array['hedging']),
('30000000-0000-0000-0000-000000002157', 'infer', '/ɪnˈfɜːr/', 'verb', 'inferir', 'From the data, we can infer a clear seasonal pattern.', 'A partir dos dados, podemos inferir um padrão sazonal claro.', 'C1', array['hedging']),
