-- Lição 356: Expressões de grau e ressalva (to some extent, to a certain degree, somewhat, relatively, by and large, for the most part)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000356', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002131", "show_image": false}'),
('20000000-0000-0000-0000-000000000356', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002135", "show_image": false}'),
('20000000-0000-0000-0000-000000000356', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002136", "show_image": false}'),
('20000000-0000-0000-0000-000000000356', 'multiple_choice', 4, '{"question": "The findings were ___ surprising to the researchers.", "audio_text": null, "options": ["somewhat", "explicit", "mandatory"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000356', 'multiple_choice', 5, '{"question": "___, the project met its original goals.", "audio_text": null, "options": ["By and large", "As if", "Lest"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000356', 'matching', 6, '{"pairs": [{"left": "to some extent", "right": "até certo ponto"}, {"left": "to a certain degree", "right": "até certo grau"}, {"left": "somewhat", "right": "um tanto"}, {"left": "relatively", "right": "relativamente"}, {"left": "by and large", "right": "de modo geral"}, {"left": "for the most part", "right": "em grande parte"}]}'),
('20000000-0000-0000-0000-000000000356', 'fill_blank', 7, '{"sentence": "The change was ___ easy to implement.", "options": ["relatively", "presumably", "arguably"], "correct": "relatively", "translation": "A mudança foi relativamente fácil de implementar."}'),
('20000000-0000-0000-0000-000000000356', 'fill_blank', 8, '{"sentence": "___, the feedback was positive.", "options": ["For the most part", "As though", "Be it"], "correct": "For the most part", "translation": "Em grande parte, o feedback foi positivo."}'),
('20000000-0000-0000-0000-000000000356', 'word_order', 9, '{"words": ["The", "results", "support", "the", "theory", "to", "a", "certain", "degree"], "correct_sentence": "The results support the theory to a certain degree", "translation": "Os resultados apoiam a teoria até certo grau"}'),
('20000000-0000-0000-0000-000000000356', 'word_order', 10, '{"words": ["The", "new", "policy", "is", "to", "some", "extent", "a", "response", "to", "employee", "feedback"], "correct_sentence": "The new policy is to some extent a response to employee feedback", "translation": "A nova política é, até certo ponto, uma resposta ao feedback dos funcionários"}'),
('20000000-0000-0000-0000-000000000356', 'reading', 11, '{"passage": "Academic and professional writing rarely makes absolute claims. Instead, writers soften statements with expressions of degree such as ''to some extent'', ''to a certain degree'', ''somewhat'' and ''relatively''. Broader qualifiers like ''by and large'' and ''for the most part'' acknowledge that a statement is generally true, while leaving room for exceptions.", "translation": "Textos acadêmicos e profissionais raramente fazem afirmações absolutas. Em vez disso, os autores suavizam declarações com expressões de grau como ''to some extent'', ''to a certain degree'', ''somewhat'' e ''relatively''. Qualificadores mais amplos como ''by and large'' e ''for the most part'' reconhecem que uma afirmação é geralmente verdadeira, deixando espaço para exceções.", "question": "What do expressions like ''by and large'' and ''for the most part'' leave room for, according to the text?", "options": ["Exceptions", "New evidence", "Formal register"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000356', 'listening', 12, '{"audio_text": "The findings were somewhat surprising to the researchers. The change was relatively easy to implement. By and large, the project met its original goals.", "question": "How easy was the change to implement, according to the audio?", "options": ["Relatively easy", "Extremely difficult", "Impossible"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000356', 'dictation', 13, '{"audio_text": "By and large, the project met its original goals.", "expected": "By and large, the project met its original goals."}'),
('20000000-0000-0000-0000-000000000356', 'typing', 14, '{"prompt_pt": "Traduza: ''Até certo ponto, os resultados foram um tanto surpreendentes, mas, de modo geral, positivos.''", "expected": "To some extent, the results were somewhat surprising, but by and large, positive.", "ai_review": true}'),

-- Lição 357: Afirmação cautelosa (tend to, appear to, seem to, presumably, plausible, arguably)
('20000000-0000-0000-0000-000000000357', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002137", "show_image": false}'),
('20000000-0000-0000-0000-000000000357', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002141", "show_image": false}'),
('20000000-0000-0000-0000-000000000357', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002142", "show_image": false}'),
('20000000-0000-0000-0000-000000000357', 'multiple_choice', 4, '{"question": "Studies ___ show a link between sleep and productivity.", "audio_text": null, "options": ["tend to", "imply", "denote"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000357', 'multiple_choice', 5, '{"question": "This is ___ the most important finding of the study.", "audio_text": null, "options": ["arguably", "mandatory", "explicit"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000357', 'matching', 6, '{"pairs": [{"left": "tend to", "right": "tender a"}, {"left": "appear to", "right": "parecer"}, {"left": "seem to", "right": "parecer"}, {"left": "presumably", "right": "presumivelmente"}, {"left": "plausible", "right": "plausível"}, {"left": "arguably", "right": "possivelmente, sem dúvida"}]}'),
('20000000-0000-0000-0000-000000000357', 'fill_blank', 7, '{"sentence": "The strategy ___ be working so far.", "options": ["appears to", "denotes", "infers"], "correct": "appears to", "translation": "A estratégia parece estar funcionando até agora."}'),
('20000000-0000-0000-0000-000000000357', 'fill_blank', 8, '{"sentence": "That explanation sounds ___, but we need more evidence.", "options": ["plausible", "mandatory", "explicit"], "correct": "plausible", "translation": "Essa explicação parece plausível, mas precisamos de mais evidências."}'),
('20000000-0000-0000-0000-000000000357', 'word_order', 9, '{"words": ["The", "data", "seem", "to", "support", "our", "initial", "hypothesis"], "correct_sentence": "The data seem to support our initial hypothesis", "translation": "Os dados parecem apoiar nossa hipótese inicial"}'),
('20000000-0000-0000-0000-000000000357', 'word_order', 10, '{"words": ["Presumably", "the", "delay", "was", "caused", "by", "a", "technical", "issue"], "correct_sentence": "Presumably the delay was caused by a technical issue", "translation": "Presumivelmente, o atraso foi causado por um problema técnico"}'),
('20000000-0000-0000-0000-000000000357', 'reading', 11, '{"passage": "Instead of stating facts as absolute certainties, careful writers use verbs like ''tend to'', ''appear to'' and ''seem to'' to signal that a claim is likely but not guaranteed. Adverbs like ''presumably'' and ''arguably'', along with the adjective ''plausible'', serve a similar function: they let the writer make a claim while acknowledging some uncertainty.", "translation": "Em vez de apresentar fatos como certezas absolutas, escritores cuidadosos usam verbos como ''tend to'', ''appear to'' e ''seem to'' para sinalizar que uma afirmação é provável, mas não garantida. Advérbios como ''presumably'' e ''arguably'', junto com o adjetivo ''plausible'', têm função parecida: permitem que o autor faça uma afirmação reconhecendo alguma incerteza.", "question": "What do verbs like ''tend to'' and ''seem to'' signal, according to the text?", "options": ["Absolute certainty", "A claim that is likely but not guaranteed", "A formal command"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000357', 'listening', 12, '{"audio_text": "Studies tend to show a link between sleep and productivity. The strategy appears to be working so far. This is arguably the most important finding of the study.", "question": "What do studies tend to show a link between, according to the audio?", "options": ["Sleep and productivity", "Deadlines and stress", "Emails and meetings"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000357', 'dictation', 13, '{"audio_text": "The data seem to support our initial hypothesis.", "expected": "The data seem to support our initial hypothesis."}'),
('20000000-0000-0000-0000-000000000357', 'typing', 14, '{"prompt_pt": "Traduza: ''Os dados parecem apoiar a hipótese, e essa é possivelmente a explicação mais plausível.''", "expected": "The data seem to support the hypothesis, and this is arguably the most plausible explanation.", "ai_review": true}'),

-- Lição 358: Frases para apresentar argumentos (it could be argued that, one could argue that, it is worth noting that, debatable, questionable, controversial)
('20000000-0000-0000-0000-000000000358', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002143", "show_image": false}'),
('20000000-0000-0000-0000-000000000358', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002145", "show_image": false}'),
('20000000-0000-0000-0000-000000000358', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002148", "show_image": false}'),
('20000000-0000-0000-0000-000000000358', 'multiple_choice', 4, '{"question": "___ the policy needs further review.", "audio_text": null, "options": ["It could be argued that", "It is high time", "Suppose that"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000358', 'multiple_choice', 5, '{"question": "The reliability of the source is ___.", "audio_text": null, "options": ["questionable", "explicit", "underlying"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000358', 'matching', 6, '{"pairs": [{"left": "it could be argued that", "right": "poderia se argumentar que"}, {"left": "one could argue that", "right": "poder-se-ia argumentar que"}, {"left": "it is worth noting that", "right": "vale notar que"}, {"left": "debatable", "right": "discutível"}, {"left": "questionable", "right": "questionável"}, {"left": "controversial", "right": "controverso"}]}'),
('20000000-0000-0000-0000-000000000358', 'fill_blank', 7, '{"sentence": "___ the sample size was small.", "options": ["It is worth noting that", "It could be argued that", "One could argue that"], "correct": "It is worth noting that", "translation": "Vale notar que o tamanho da amostra era pequeno."}'),
('20000000-0000-0000-0000-000000000358', 'fill_blank', 8, '{"sentence": "The new regulation has proven ___ among experts.", "options": ["controversial", "plausible", "relatively"], "correct": "controversial", "translation": "A nova regulamentação se mostrou controversa entre especialistas."}'),
('20000000-0000-0000-0000-000000000358', 'word_order', 9, '{"words": ["One", "could", "argue", "that", "the", "risks", "outweigh", "the", "benefits"], "correct_sentence": "One could argue that the risks outweigh the benefits", "translation": "Poder-se-ia argumentar que os riscos superam os benefícios"}'),
('20000000-0000-0000-0000-000000000358', 'word_order', 10, '{"words": ["Whether", "the", "approach", "is", "effective", "remains", "debatable"], "correct_sentence": "Whether the approach is effective remains debatable", "translation": "Se a abordagem é eficaz ainda é discutível"}'),
('20000000-0000-0000-0000-000000000358', 'reading', 11, '{"passage": "When presenting an argument in academic writing, phrases like ''it could be argued that'' and ''one could argue that'' distance the writer from the claim, presenting it as one possible view rather than an absolute truth. ''It is worth noting that'' introduces a relevant detail, while adjectives like ''debatable'', ''questionable'' and ''controversial'' signal that a topic invites disagreement.", "translation": "Ao apresentar um argumento em textos acadêmicos, frases como ''it could be argued that'' e ''one could argue that'' distanciam o autor da afirmação, apresentando-a como uma visão possível, e não uma verdade absoluta. ''It is worth noting that'' introduz um detalhe relevante, enquanto adjetivos como ''debatable'', ''questionable'' e ''controversial'' sinalizam que um tema convida ao desacordo.", "question": "What do phrases like ''it could be argued that'' do, according to the text?", "options": ["State an absolute truth", "Distance the writer from the claim", "Give a direct command"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000358', 'listening', 12, '{"audio_text": "It could be argued that the policy needs further review. It is worth noting that the sample size was small. The new regulation has proven controversial among experts.", "question": "What is worth noting, according to the audio?", "options": ["The sample size was small", "The policy is perfect", "The regulation is popular"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000358', 'dictation', 13, '{"audio_text": "It could be argued that the policy needs further review.", "expected": "It could be argued that the policy needs further review."}'),
('20000000-0000-0000-0000-000000000358', 'typing', 14, '{"prompt_pt": "Traduza: ''Poderia se argumentar que o tema é controverso, mas vale notar que os dados são questionáveis.''", "expected": "It could be argued that the topic is controversial, but it is worth noting that the data are questionable.", "ai_review": true}'),

